UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='동시 처리 수가 증가하면서 실행 대기열이 240개로 늘었다. 처리기 사용률은 98%이고 디스크 대기는 1%이다. 전 지점의 출금이 20분째 한 건도 처리되지 않는다. 대체 창구도 같은 서비스를 사용한다. 지난주 가상 기록과 장비·오류번호·발생 순서가 같고 당시 조치 후 멈췄던 현상이 다시 나타났다.',expected_type='RESOURCE',expected_severity='P1',expected_department='PLATFORM',expected_recurrence=TRUE,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-001';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='힙 점유가 수거 직후에도 97%에 머물며 새 객체를 만들지 못하고 프로세스가 종료되었다. 일부 조회가 지연되지만 자금 이동은 정상이며 재시도하면 조회도 완료된다. 최근 90일의 전체 기록을 검토했으며 같은 자산과 오류 조합의 선행 건은 없다.',expected_type='RESOURCE',expected_severity='P2',expected_department='PLATFORM',expected_recurrence=FALSE,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-002';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='프로세스의 열린 파일 수가 65535에 도달했다. 새 소켓 생성 시 Too many open files가 기록된다.',expected_type='RESOURCE',expected_severity=NULL,expected_department='PLATFORM',expected_recurrence=NULL,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-003';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='임시 파일 영역의 남은 공간은 0바이트이다. 로그 파일 쓰기가 실패하지만 거래 연결은 정상이다. 가상 카드 결제가 모든 가맹점에서 거절되고 예비 경로 전환도 실패했다.',expected_type='RESOURCE',expected_severity='P1',expected_department='PLATFORM',expected_recurrence=NULL,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-004';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='저장 공간은 40% 남았지만 inode 사용량이 100%라 신규 파일을 만들지 못한다. 한 지역의 예약 기능만 실패한다. 즉시 이체와 다른 지역 서비스는 정상이다. 동일 버전의 동일 배치에서 이틀 전 처리한 것과 같은 오류 흐름이 다시 재현됐다.',expected_type='RESOURCE',expected_severity='P2',expected_department='PLATFORM',expected_recurrence=TRUE,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-005';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='컨테이너 메모리 제한 2GiB를 넘긴 직후 종료 코드 137과 OOMKilled가 함께 기록됐다. 서비스 개통 이후 보관한 모든 기록에서 이 요청 실패는 처음 확인됐다.',expected_type='RESOURCE',expected_severity=NULL,expected_department='PLATFORM',expected_recurrence=FALSE,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-006';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='전체 처리기는 여유가 있지만 해당 컨테이너의 CPU throttling 비율이 92%이고 quota에 도달했다. 급여 지급 마감까지 10분인데 대상 8만 건이 전부 대기 중이며 수기 처리할 수 없다.',expected_type='RESOURCE',expected_severity='P1',expected_department='PLATFORM',expected_recurrence=NULL,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-007';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='수거 시간이 전체 실행 시간의 88%이며 old 영역은 수거 후에도 99%이다. 100건 중 4건이 처음에 지연됐지만 재처리로 완료됐다. 고객 자금에는 영향이 없다.',expected_type='RESOURCE',expected_severity='P2',expected_department='PLATFORM',expected_recurrence=NULL,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-008';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='스레드 4096개가 모두 사용 중이고 새 스레드를 생성할 수 없다는 시스템 오류가 관측된다. 이전 장애의 로그 지문과 이번 지문을 대조한 결과 해당 구성요소와 예외 지점이 모두 같다.',expected_type='RESOURCE',expected_severity=NULL,expected_department='PLATFORM',expected_recurrence=TRUE,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-009';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='스왑 입출력이 초당 2GB이고 가용 메모리는 10MB이다. 애플리케이션 예외는 없다. 주센터와 예비센터 모두 계좌 입금을 처리하지 못해 고객 자금 반영이 중단됐다. 과거 비슷한 제목의 건은 다른 장비와 다른 원인이었고 이번 오류에 해당하는 기록은 없다.',expected_type='RESOURCE',expected_severity='P1',expected_department='PLATFORM',expected_recurrence=FALSE,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-010';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='공유 메모리 세그먼트 할당 한도에 도달하여 배치 프로세스가 시작되지 않는다. 월별 통계 화면만 사용할 수 없고 핵심 금융 거래는 모두 정상 동작한다.',expected_type='RESOURCE',expected_severity='P2',expected_department='PLATFORM',expected_recurrence=NULL,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-011';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='단일 호스트의 파일시스템 읽기 지연이 4초이며 장치 큐가 300개다. 다른 호스트는 정상이다.',expected_type='RESOURCE',expected_severity=NULL,expected_department='PLATFORM',expected_recurrence=NULL,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-012';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='조회 세션 120개가 동일한 미완료 거래의 행 잠금 해제를 기다리고 있다. 국내 전체 채널의 이체 성공 건수가 0으로 내려갔다. 대체 결제 경로는 없다. 지난달 같은 계층의 같은 오류를 처리한 이력이 있으며 이번에도 직전 설정 변경과 현상이 일치한다.',expected_type='DATABASE',expected_severity='P1',expected_department='DATABASE',expected_recurrence=TRUE,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-013';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='대기 그래프에서 두 거래가 서로 가진 행을 요청한다. 희생 거래에 ORA-00060이 남았다. 주 회선은 문제가 있지만 예비 회선을 통해 전체 거래가 처리된다. 평소보다 2초 느리다. 최근 기록의 반복 경보는 시험 메시지였으며 이번 현상에 대응하는 이전 장애는 없음을 확인했다.',expected_type='DATABASE',expected_severity='P2',expected_department='DATABASE',expected_recurrence=FALSE,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-014';
