UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='복제본 적용 지연이 7200초이며 쓰기 원본에는 최신 거래가 존재한다. 가상 잔액이 잘못 차감되는 현상이 여러 계정에서 재현돼 모든 금융 거래를 차단했다.',expected_type='DATABASE',expected_severity='P1',expected_department='DATABASE',expected_recurrence=NULL,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-016';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='조회 실행계획이 인덱스 탐색에서 전체 스캔으로 바뀐 뒤 처리시간이 200배 늘었다. 배치가 예상보다 10분 늦었지만 마감까지 6시간 남았고 온라인 거래는 정상이다. 일주일 전 복구한 서버에서 동일 요청으로 같은 실패 순서가 재현됐음을 담당자가 확인했다.',expected_type='DATABASE',expected_severity='P2',expected_department='DATABASE',expected_recurrence=TRUE,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-017';
