UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='테이블스페이스 확장이 한도에 도달했고 INSERT에서 ORA-01653이 발생한다. 전체 거래의 최종 결과를 확인할 수 없어 중복 지급 위험 때문에 서비스가 중지됐다.',expected_type='DATABASE',expected_severity='P1',expected_department='DATABASE',expected_recurrence=NULL,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-019';
