UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='읽기 전용 복제본으로 쓰기가 전달되어 read-only transaction 오류가 반복된다. 가상 이력의 이전 두 건과 이번 건은 같은 인스턴스·오류번호·조건을 갖는다.',expected_type='DATABASE',expected_severity=NULL,expected_department='DATABASE',expected_recurrence=TRUE,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-021';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='주 인스턴스의 연결 상한 300개가 모두 점유되어 신규 세션이 거절된다. 영업점과 모바일에서 모두 인증을 완료할 수 없고 대체 로그인 수단도 동작하지 않는다. 동일 번호의 이전 알림은 정상 업무 거절이었고 이번 오류 상태로 발생한 건은 처음이다.',expected_type='DATABASE',expected_severity='P1',expected_department='DATABASE',expected_recurrence=FALSE,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-022';
UPDATE evaluation_cases SET dataset_version='ko-incident-v2',category='TECHNICAL_KO',raw_message=NULL,observations='실행 중인 스키마 변경이 배타 잠금을 유지하며 모든 조회가 relation lock을 기다린다. 대체 화면을 사용하면 같은 업무를 처리할 수 있어 안내 후 서비스가 계속되고 있다.',expected_type='DATABASE',expected_severity='P2',expected_department='DATABASE',expected_recurrence=NULL,expected_review=FALSE,expected_eligible=TRUE,rationale='관측된 고장 계층의 담당 부서를 평가한다. 고객 영향·과거 이력은 주어지지 않아 심각도·재발은 채점하지 않는다.' WHERE id='KO-023';
